    department VARCHAR(255) NOT NULL DEFAULT '',
    employment_type VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (employment_type IN ('permanent', 'fixed-term', 'agency', 'contractor', 'apprentice', 'volunteer', 'other', '')),
